INSERT INTO `semantic_profiles` VALUES (1,'resume',8,'sep_v1','resume_profiler_v1','sep_schema_v1','393092ae32e89742c009ff56e9e6ca79bf6d91bda645857105811ebd68afab82','hy3','hy3-preview','high','湖南科技大学软件工程本科在读生，有Java后端开发实习经历，完成多个校园及个人后端项目，具备基础后端开发能力，投递后端开发实习岗位。','[\"有3个月企业后端开发实习经历，参与18个接口开发，熟悉企业项目开发全流程。\", \"完成3个Java后端相关项目，覆盖鉴权、缓存、幂等设计等核心后端开发场景。\", \"具备数据库表设计、SQL优化、接口文档维护等后端开发必备工程实践能力。\", \"能合理使用AI工具辅助开发，且会对生成内容验证，具备良好的开发规范意识。\"]','[{\"label\": \"复杂系统架构理解不足\", \"severity\": \"medium\", \"confidence\": 0.9, \"explanation\": \"候选人自述对高并发、分布式等复杂架构理解有限，暂无法适配中高级后端开发需求\", \"evidence_text\": \"当前我的能力仍处于本科实习生阶段，对高并发、分布式架构和复杂系统设计理解还不深入\"}, {\"label\": \"技术深度有待提升\", \"severity\": \"low\", \"confidence\": 0.85, \"explanation\": \"候选人在缓存一致性、消息队列等进阶技术方向经验不足，技术深度仍需积累\", \"evidence_text\": \"后续希望继续提升 Java 后端开发能力，重点补齐 MySQL 查询优化、Redis 缓存一致性、消息队列、Linux 部署、日志排查和真实业务系统设计经验\"}]','[\"Java后端开发实习\", \"企业后台系统开发实习\", \"校园服务类后端开发实习\"]','{\"tags\": [{\"weight\": 0.95, \"category\": \"role_direction\", \"tag_code\": \"java_backend_development\", \"tag_label\": \"Java后端开发\", \"confidence\": 0.95, \"explanation\": \"明确候选人的核心求职方向，是匹配后端相关岗位的核心依据\", \"evidence_text\": \"我目前主要投递 Java 后端开发、后端开发实习、企业应用开发和后台系统开发相关岗位\", \"source_section\": \"补充信息\", \"is_user_visible\": true}, {\"weight\": 0.9, \"category\": \"role_direction\", \"tag_code\": \"backend_development_intern\", \"tag_label\": \"后端开发实习\", \"confidence\": 0.9, \"explanation\": \"候选人当前求职定位为实习岗位，是校园招聘场景下的核心匹配方向\", \"evidence_text\": \"我目前主要投递 Java 后端开发、后端开发实习、企业应用开发和后台系统开发相关岗位\", \"source_section\": \"补充信息\", \"is_user_visible\": true}, {\"weight\": 0.85, \"category\": \"role_direction\", \"tag_code\": \"enterprise_application_backend_development\", \"tag_label\": \"企业应用后端开发\", \"confidence\": 0.85, \"explanation\": \"候选人有企业后台管理系统开发实习经历，适配企业应用开发方向\", \"evidence_text\": \"我目前主要投递 Java 后端开发、后端开发实习、企业应用开发和后台系统开发相关岗位\", \"source_section\": \"补充信息\", \"is_user_visible\": true}, {\"weight\": 0.95, \"category\": \"technical_skill\", \"tag_code\": \"java_springboot_mysql_backend_development\", \"tag_label\": \"Java Spring Boot MySQL后端开发\", \"confidence\": 0.95, \"explanation\": \"候选人的核心技术栈，是后端开发岗位匹配的核心能力依据\", \"evidence_text\": \"项目使用 Java、Spring Boot、MyBatis、MySQL、Redis、JWT 和 Swagger 实现，我主要负责后端接口开发、数据库表设计、登录鉴权和前后端联调\", \"source_section\": \"项目经历-校园失物招领系统\", \"is_user_visible\": true}, {\"weight\": 0.85, \"category\": \"technical_skill\", \"tag_code\": \"redis_basic_application\", \"tag_label\": \"Redis基础应用\", \"confidence\": 0.9, \"explanation\": \"候选人具备Redis基础使用能力，可支撑缓存相关基础开发需求\", \"evidence_text\": \"为了减少首页文章列表和文章详情的重复查询，我使用 Redis 缓存热门文章详情和首页文章列表，并在文章更新、删除和评论状态变更后清理相关缓存\", \"source_section\": \"项目经历-个人博客与学习笔记系统\", \"is_user_visible\": true}, {\"weight\": 0.9, \"category\": \"technical_skill\", \"tag_code\": \"restful_api_design_and_development\", \"tag_label\": \"RESTful API设计与开发\", \"confidence\": 0.9, \"explanation\": \"接口开发是后端核心工作，该能力是候选人完成多个项目的基础\", \"evidence_text\": \"专业技能：JWT、RESTful API 设计、数据库表结构设计、索引基础、分页查询、参数校验、登录鉴权、资源归属校验、接口幂等基础、缓存设计、Swagger\", \"source_section\": \"专业技能\", \"is_user_visible\": true}, {\"weight\": 0.88, \"category\": \"engineering_capability\", \"tag_code\": \"database_table_design_and_optimization\", \"tag_label\": \"数据库表设计与优化\", \"confidence\": 0.88, \"explanation\": \"数据库设计及优化能力是后端开发的核心工程能力，直接影响系统性能\", \"evidence_text\": \"针对前端联调中出现的字段含义不清、空值返回不统一、状态枚举展示不一致等问题，我补充 Swagger 注释和字段说明，并和前端同学对齐返回结构。测试阶段，我根据测试反馈修复参数为空、分页页码异常、时间格式错误、状态筛选不生效、删除后列表未刷新等问题。对于员工列表和审批记录等高频查询接口，我协助排查慢查询原因，使用 EXPLAIN 查看 SQL 执行情况，并在正式员工指导下对部门 ID、状态、创建时间等字段增加索引\", \"source_section\": \"实习经历\", \"is_user_visible\": true}, {\"weight\": 0.85, \"category\": \"engineering_capability\", \"tag_code\": \"interface_idempotent_design\", \"tag_label\": \"接口幂等设计\", \"confidence\": 0.85, \"explanation\": \"接口幂等是后端开发的重要工程能力，可避免重复提交带来的数据问题\", \"evidence_text\": \"为了理解后端接口在重复点击、网络重试和并发请求场景下可能出现的数据重复问题，完成一个接口重复提交与幂等处理练习项目，模拟认领申请提交、评论提交和订单提交等业务场景。项目中设计了请求 token 生成、Redis 校验、业务处理和 token 失效流程，使用 Redis 的 SETNX 思路对短时间内重复提交进行拦截\", \"source_section\": \"项目经历-接口重复提交与幂等处理练习\", \"is_user_visible\": true}, {\"weight\": 0.9, \"category\": \"engineering_capability\", \"tag_code\": \"frontend_backend_joint_debugging\", \"tag_label\": \"前后端联调\", \"confidence\": 0.92, \"explanation\": \"前后端联调是后端开发必备的协作能力，候选人多个项目均有相关实践\", \"evidence_text\": \"我主要负责后端接口开发、数据库表设计、登录鉴权和前后端联调\", \"source_section\": \"项目经历-校园失物招领系统\", \"is_user_visible\": true}, {\"weight\": 0.8, \"category\": \"domain_context\", \"tag_code\": \"campus_scene_project_experience\", \"tag_label\": \"校园场景项目经验\", \"confidence\": 0.9, \"explanation\": \"校园场景项目经验可适配校园服务类相关后端开发岗位需求\", \"evidence_text\": \"面向校内学生失物招领场景，开发校园失物招领系统，支持用户注册登录、失物信息发布、失物列表查询、关键词搜索、留言评论、认领申请和状态修改等功能\", \"source_section\": \"项目经历-校园失物招领系统\", \"is_user_visible\": true}, {\"weight\": 0.85, \"category\": \"domain_context\", \"tag_code\": \"enterprise_background_management_system_experience\", \"tag_label\": \"企业后台管理系统开发经验\", \"confidence\": 0.88, \"explanation\": \"企业后台管理系统是后端开发的常见业务领域，该经验适配相关岗位\", \"evidence_text\": \"参与企业内部后台管理系统的后端接口开发，项目主要服务员工信息维护、部门管理、审批记录查询和基础数据统计等场景\", \"source_section\": \"实习经历\", \"is_user_visible\": true}, {\"weight\": 0.95, \"category\": \"experience_signal\", \"tag_code\": \"backend_development_internship_experience\", \"tag_label\": \"后端开发实习经历\", \"confidence\": 0.95, \"explanation\": \"企业实习经历是校园招聘中评估候选人实践能力的重要信号\", \"evidence_text\": \"长沙某软件科技有限公司｜后端开发实习生｜2025-03-2025-05｜参与企业内部后台管理系统的后端接口开发，实习期间参与开发和维护 18 个接口，修复测试阶段反馈问题 26 项，负责模块最终在内部测试环境完成验收\", \"source_section\": \"实习经历\", \"is_user_visible\": true}, {\"weight\": 0.9, \"category\": \"experience_signal\", \"tag_code\": \"multiple_backend_project_landing\", \"tag_label\": \"多个后端项目落地\", \"confidence\": 0.92, \"explanation\": \"多个项目落地证明候选人具备将技术能力转化为实际产出的能力\", \"evidence_text\": \"已完成校园失物招领系统、个人博客与学习笔记系统等项目，并在企业实习中参与后台管理系统接口开发、测试反馈修复和接口文档维护\", \"source_section\": \"教育经历\", \"is_user_visible\": true}, {\"weight\": 0.75, \"category\": \"experience_signal\", \"tag_code\": \"ai_assisted_development_ability\", \"tag_label\": \"AI辅助开发能力\", \"confidence\": 0.85, \"explanation\": \"AI辅助开发是当前开发提效的重要方式，该能力可提升候选人开发效率\", \"evidence_text\": \"会使用 AI 工具辅助理解框架报错、生成接口测试样例、整理数据库表字段、补充 Swagger 接口说明和梳理 Bug 排查思路。对于 AI 生成的代码，会结合课程资料、官方文档、本地运行结果和接口测试结果进行核对，不直接复制未经验证的生成代码\", \"source_section\": \"AI应用技能\", \"is_user_visible\": true}], \"risks\": [{\"label\": \"复杂系统架构理解不足\", \"severity\": \"medium\", \"confidence\": 0.9, \"explanation\": \"候选人自述对高并发、分布式等复杂架构理解有限，暂无法适配中高级后端开发需求\", \"evidence_text\": \"当前我的能力仍处于本科实习生阶段，对高并发、分布式架构和复杂系统设计理解还不深入\"}, {\"label\": \"技术深度有待提升\", \"severity\": \"low\", \"confidence\": 0.85, \"explanation\": \"候选人在缓存一致性、消息队列等进阶技术方向经验不足，技术深度仍需积累\", \"evidence_text\": \"后续希望继续提升 Java 后端开发能力，重点补齐 MySQL 查询优化、Redis 缓存一致性、消息队列、Linux 部署、日志排查和真实业务系统设计经验\"}], \"strengths\": [\"有3个月企业后端开发实习经历，参与18个接口开发，熟悉企业项目开发全流程。\", \"完成3个Java后端相关项目，覆盖鉴权、缓存、幂等设计等核心后端开发场景。\", \"具备数据库表设计、SQL优化、接口文档维护等后端开发必备工程实践能力。\", \"能合理使用AI工具辅助开发，且会对生成内容验证，具备良好的开发规范意识。\"], \"profile_notes\": \"候选人为本科在读实习生，能力定位为基础后端开发，适配实习类岗位，暂不适合要求高并发、分布式架构的中高级后端岗位，后续成长空间较大。\", \"fit_directions\": [\"Java后端开发实习\", \"企业后台系统开发实习\", \"校园服务类后端开发实习\"], \"summary_sentence\": \"湖南科技大学软件工程本科在读生，有Java后端开发实习经历，完成多个校园及个人后端项目，具备基础后端开发能力，投递后端开发实习岗位。\"}','verified','','2026-06-12 12:15:13','2026-06-12 12:15:13'),(2,'job',10001,'sep_v1','job_profiler_v1','sep_schema_v1','8650c0caeb9a514ba83c8274edd5883e45437630e7647de8d2b5b73777773b2f','hy3','hy3-preview','high','该岗位为后台开发方向，主要负责公司产品功能实现优化、关键服务与基础设施构建维护，要求扎实编程基础与多领域软件专业知识。','[\"要求扎实的编程能力，熟练掌握至少一门指定开发语言\", \"需要熟悉TCP/UDP网络协议、进程间通讯编程能力\", \"需具备算法、操作系统、软件工程等多领域专业软件知识\"]','[\"岗位可能更偏好计算机相关专业背景的候选人，以匹配要求的多领域软件专业知识\", \"岗位可能更看重有实际后台服务开发、基础设施构建相关实践经历的候选人\"]','[\"有后台服务开发、网络编程相关实践经历的软件开发候选人\", \"掌握C/C++/Java/Go其中一门语言且具备扎实计算机专业基础的候选人\", \"了解分布式系统、云原生技术相关知识的技术储备型候选人\"]','{\"tags\": [{\"weight\": 10, \"category\": \"role_direction\", \"tag_code\": \"后台开发\", \"tag_label\": \"后台开发\", \"confidence\": 1, \"explanation\": \"岗位明确属于后台开发方向\", \"evidence_text\": \"岗位名称：软件开发-后台开发方向\", \"source_section\": \"岗位名称\", \"